    ---------------------------------------------------------------------------
    -- 1. VALIDA A QUANTIDADE DE ACADEMIAS DAS REDES
    ---------------------------------------------------------------------------

    IF (SELECT COUNT(*) FROM Academia WHERE cnpj IN (
        '90100000000156',
        '90100001000109',
        '90100002000145',
        '90100003000190',
        '90100004000134',
        '90100005000189',
        '90100008000112',
        '90100009000167',
        '90100010000191',
        '90100011000136',
        '90100016000169',
        '90100017000103',
        '90100018000158',
        '90100019000100',
        '90100020000127'
    )) <> 15
        THROW 51001, 'LOGYM: esperado encontrar exatamente 15 academias Smart Fit.', 1;

    IF (SELECT COUNT(*) FROM Academia WHERE cnpj IN (
        '90100006000123',
        '90100007000178',
        '90100012000180',
        '90100013000125',
        '90100014000170',
        '90100015000114',
        '90100021000171',
        '90100022000116',
        '90100023000160'
    )) <> 9
        THROW 51002, 'LOGYM: esperado encontrar exatamente 9 academias Bluefit.', 1;

    ---------------------------------------------------------------------------
    -- 2. MONTA ORDEM DETERMINÍSTICA DAS ACADEMIAS
    ---------------------------------------------------------------------------

    ;WITH SmartOrdenadas AS
    (
        SELECT
            a.id,
            ROW_NUMBER() OVER (ORDER BY LOWER(a.nome), a.cnpj) - 1 AS indice
        FROM Academia a
        WHERE a.cnpj IN (
            '90100000000156',
        '90100001000109',
        '90100002000145',
        '90100003000190',
        '90100004000134',
        '90100005000189',
        '90100008000112',
        '90100009000167',
        '90100010000191',
        '90100011000136',
        '90100016000169',
        '90100017000103',
        '90100018000158',
        '90100019000100',
        '90100020000127'
        )
    )
    INSERT INTO #AcademiaAlvoLOGYM (rede, academiaId, indice)
    SELECT 'SMART_FIT', id, indice
    FROM SmartOrdenadas;

    ;WITH BlueOrdenadas AS
    (
        SELECT
            a.id,
            ROW_NUMBER() OVER (ORDER BY LOWER(a.nome), a.cnpj) - 1 AS indice
        FROM Academia a
        WHERE a.cnpj IN (
            '90100006000123',
        '90100007000178',
        '90100012000180',
        '90100013000125',
        '90100014000170',
        '90100015000114',
        '90100021000171',
        '90100022000116',
        '90100023000160'
        )
    )
    INSERT INTO #AcademiaAlvoLOGYM (rede, academiaId, indice)
    SELECT 'BLUEFIT', id, indice
    FROM BlueOrdenadas;

    ---------------------------------------------------------------------------
    -- 3. REMOVE SOMENTE A CARGA DE FOTOS DESSAS REDES
    --    Necessário porque a versão anterior já foi executada.
    ---------------------------------------------------------------------------

    DELETE f
    FROM FotoAcademia f
    INNER JOIN #AcademiaAlvoLOGYM aa
        ON aa.academiaId = f.academia_id;

    ---------------------------------------------------------------------------
    -- 4. PRINCIPAL: UMA FACHADA DIFERENTE DISTRIBUÍDA PELO POOL
    ---------------------------------------------------------------------------

    INSERT INTO FotoAcademia
    (
        foto,
        tipoArquivo,
        academia_id,
        dataCadastro,
        statusFoto,
        principal
    )
    SELECT
        s.foto,
        s.tipoArquivo,
        aa.academiaId,
        GETDATE(),
        'ATIVO',
        1
    FROM #AcademiaAlvoLOGYM aa
    INNER JOIN #FotoSeedLOGYM s
        ON s.rede = aa.rede
       AND s.grupo = 'FACHADA'
       AND s.ordemPool =
       (
           aa.indice %
           (
               SELECT COUNT(*)
               FROM #FotoSeedLOGYM x
               WHERE x.rede = aa.rede
                 AND x.grupo = 'FACHADA'
           )
       ) + 1;

    ---------------------------------------------------------------------------
    -- 5. SECUNDÁRIAS: QUATRO INTERIORES/EQUIPAMENTOS POR ACADEMIA
    --    O deslocamento pelo índice distribui o pool entre as unidades.
    ---------------------------------------------------------------------------

    INSERT INTO FotoAcademia
    (
        foto,
        tipoArquivo,
        academia_id,
        dataCadastro,
        statusFoto,
        principal
    )
    SELECT
        s.foto,
        s.tipoArquivo,
        aa.academiaId,
        GETDATE(),
        'ATIVO',
        0
    FROM #AcademiaAlvoLOGYM aa
    CROSS JOIN
    (
        VALUES (0), (1), (2), (3)
    ) AS deslocamento(valor)
    INNER JOIN #FotoSeedLOGYM s
        ON s.rede = aa.rede
       AND s.grupo = 'INTERIOR'
       AND s.ordemPool =
       (
           ((aa.indice * 4) + deslocamento.valor) %
           (
               SELECT COUNT(*)
               FROM #FotoSeedLOGYM x
               WHERE x.rede = aa.rede
                 AND x.grupo = 'INTERIOR'
           )
       ) + 1;

    ---------------------------------------------------------------------------
    -- 6. VALIDA ANTES DO COMMIT
    ---------------------------------------------------------------------------

    IF EXISTS
    (
        SELECT aa.academiaId
        FROM #AcademiaAlvoLOGYM aa
        LEFT JOIN FotoAcademia f
            ON f.academia_id = aa.academiaId
        GROUP BY aa.academiaId
        HAVING COUNT(f.id) <> 5
            OR SUM(CASE WHEN f.principal = 1 THEN 1 ELSE 0 END) <> 1
    )
        THROW 51003, 'LOGYM: cada Smart Fit/Bluefit deve terminar com exatamente 5 fotos e 1 principal.', 1;

    -- Garante que não há repetição binária dentro da mesma academia.
    IF EXISTS
    (
        SELECT academia_id
        FROM
        (
            SELECT
                f.academia_id,
                HASHBYTES('SHA2_256', f.foto) AS hashFoto
            FROM FotoAcademia f
            INNER JOIN #AcademiaAlvoLOGYM aa
                ON aa.academiaId = f.academia_id
        ) h
        GROUP BY academia_id, hashFoto
        HAVING COUNT(*) > 1
    )
        THROW 51004, 'LOGYM: foi detectada imagem repetida dentro da mesma academia.', 1;

    COMMIT TRANSACTION;

    DROP TABLE #AcademiaAlvoLOGYM;
    DROP TABLE #FotoSeedLOGYM;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;

    IF OBJECT_ID('tempdb..#AcademiaAlvoLOGYM') IS NOT NULL
        DROP TABLE #AcademiaAlvoLOGYM;

    IF OBJECT_ID('tempdb..#FotoSeedLOGYM') IS NOT NULL
        DROP TABLE #FotoSeedLOGYM;

    THROW;
END CATCH;
GO

